=// ── Lê o output do GPT ────────────────────────────────────────────────────────
const ctx   = $('📌 Prepara Contexto').item.json;
const input = $input.item.json;

let gptText = '';

if (input?.message?.content) {
  gptText = input.message.content;
} else if (input?.choices?.[0]?.message?.content) {
  gptText = input.choices[0].message.content;
} else if (typeof input?.content === 'string') {
  gptText = input.content;
} else {
  gptText = JSON.stringify(input);
}

// ── Parse do JSON (remove cercas de markdown) ─────────────────────────────────
let atividade;
try {
  if (typeof gptText === 'object' && gptText !== null) {
    atividade = gptText;
  } else {
    let raw = String(gptText).split('`').join('').trim();
    if (raw.startsWith('json')) raw = raw.slice(4).trim();
    atividade = JSON.parse(raw);
  }
} catch(e) {
  return { detectado: false, instance: ctx.instance, remoteJid: ctx.remoteJid };
}

// ── Sanitiza alternativas que vieram como objetos ─────────────────────────────
if (atividade.niveis) {
  atividade.niveis.forEach(nivel => {
    if (!nivel.questoes) return;
    nivel.questoes.forEach(q => {
      // Corrige [object Object] nas alternativas (aceita chaves PT e EN)
      if (q.alternativas && Array.isArray(q.alternativas)) {
        q.alternativas = q.alternativas.map(alt => {
          if (typeof alt === 'string') return alt;
          if (typeof alt === 'object' && alt !== null) {
            return alt.texto || alt.text || alt.label || alt.descricao || alt.opcao || alt.value || alt.content || Object.values(alt)[0] || '';
          }
          return String(alt);
        }).filter(alt => String(alt).trim() !== '');
      }

      if (q.linha_resposta && typeof q.linha_resposta !== 'string') {
        q.linha_resposta = String(q.linha_resposta);
      }

      if (q.linhas_resposta !== undefined) {
        q.linhas_resposta = parseInt(q.linhas_resposta) || 0;
      }

      if (q.tipo_ilustracao && typeof q.tipo_ilustracao !== 'string') {
        q.tipo_ilustracao = null;
      }
    });
  });
}

// ── Injeta contexto ───────────────────────────────────────────────────────────
atividade.instance    = ctx.instance;
atividade.remoteJid   = ctx.remoteJid;

// 🔒 SEGURANÇA: a chave do Pixabay NÃO fica mais hardcoded aqui.
// A API usa a variável PIXABAY_API_KEY do próprio arquivo .env dela.
// Se quiser forçar pelo n8n, defina PIXABAY_API_KEY no servidor n8n e descomente:
// atividade.pixabay_key = $env.PIXABAY_API_KEY || '';

return atividade;
